            if rate_check is not None:
                allowed, headers = rate_check(
                    procedure, principal, str(environ.get("REMOTE_ADDR", ""))
                )
                if not allowed:
                    return _error(start, "resource_exhausted", "Too many requests", headers)
            command = procedure.input.model_validate(data)
            value = (
                service.execute(command, principal)
                if procedure.principal
                else service.execute(command)
            )
